#!/usr/bin/env bash
# Dev-shell runtime bootstrap for ema, sourced by this repo's flake
# (./bin/dev/shell-enter.sh <PROJECT_NAME>). Must be sourced (not executed):
# the env exports must reach the interactive shell, and the MariaDB stop
# trap must bind to it. Must run from the repo root ($PWD).
#
# ema has no .env: machine paths are owned by the Makefile and re-derived
# here (relative to $PWD); the dev connection config lives in the
# per-instance var/sandbox/<name>-<guid>/reuter.ini (generated by
# 'ema sandbox'), never in a shell export. EMA_TARGET is left unset here so
# the prod default applies (the only verb that still consults it is the
# dbname-addressed one, mariadb); sandbox stays an explicit opt-in
# (`EMA_TARGET=sandbox ema mariadb <db>`). This script exports the repo/lib
# locations, puts the repo root on PATH (so the bare `ema` command resolves),
# installs the PROJECT_NAME-scoped tmux alias, and binds an EXIT
# trap that stops the sandbox MariaDB instances when the shell exits. No
# daemon is started on entry: instances are started by 'ema sandbox' (on
# first build) and stopped on shell exit. Prompt styling (PS1) stays in the
# flake shellHook so users can customize it directly.

if ! (return 0 2>/dev/null); then
    echo "shell-enter.sh must be sourced, not executed" >&2
    exit 1
fi

if [ -z "${1:-}" ]; then
    echo "usage: source shell-enter.sh <PROJECT_NAME>" >&2
    return 1 2>/dev/null || exit 1
fi
PROJECT_NAME="$1"

export EMA_REPO_PATH="$PWD"
export EMA_LIB="$EMA_REPO_PATH/src"

# Put the repo root on PATH so the bare `ema` command resolves inside the dev
# shell (the flake's shellHook sources this script; nothing else adds it).
export PATH="$PWD:$PATH"

# Sandbox MariaDB instances (var/sandbox/<name>-<guid>/) are started by
# 'ema sandbox' when a database is first built, and stopped when this shell
# exits. Nothing is started on entry.
_ema_sandbox_shutdown() {
    local status=$?
    local dir pidfile pid
    for dir in "$EMA_REPO_PATH"/var/sandbox/*/; do
        [[ -d "$dir" ]] || continue
        pidfile="$dir/mysql.pid"
        [[ -f "$pidfile" ]] || continue
        pid="$(cat "$pidfile" 2>/dev/null)"
        if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null; then
            # At least one instance is alive: stop them all.
            echo "Stopping sandbox MariaDB instances..."
            ( cd "$EMA_REPO_PATH" && ./ema stop -q ) >/dev/null 2>&1 || true
            break
        fi
    done
    return $status
}
trap _ema_sandbox_shutdown EXIT

# Inherit nix shell env in tmux (doesn't include PS1)
# Requires 'set -g default-command ...' in .tmux.conf
alias tmux="command tmux -L \$PROJECT_NAME new-session -A -s \$PROJECT_NAME"
